arguments.command:
BUNDLE_GEMFILE=Gemfile.saas bundle exec ruby -rstripe -rjson -e '
secret = "whsec_test_secret"
payload = {
  id: "evt_123",
  object: "event",
  type: "customer.subscription.updated",
  data: {
    object: {
      id: "sub_123",
      object: "subscription",
      customer: "cus_123",
      status: "active",
      cancel_at: nil,
      current_period_end: 1700000000,
      items: {
        object: "list",
        data: [
          {
            id: "si_123",
            object: "subscription_item",
            current_period_end: 1700000000,
            price: { id: "price_monthly_v1", object: "price", unit_amount: 2000 }
          }
        ]
      },
      metadata: { account_id: "acc_123", plan_key: "monthly_v1" }
    }
  }
}.to_json
ts = Time.now
sig = Stripe::Webhook::Signature.compute_signature(ts, payload, secret)
header = Stripe::Webhook::Signature.generate_header(ts, sig)
event = Stripe::Webhook.construct_event(payload, header, secret)
sub = event.data.object
puts "type: #{event.type}"
puts "sub class: #{sub.class}"
puts "sub.id: #{sub.id}, customer: #{sub.customer}, status: #{sub.status}"
puts "sub[:current_period_end]: #{sub[:current_period_end]}"
puts "item period end: #{sub.items.data.first.current_period_end}"
puts "price id: #{sub.items.data.first.price.id}"
puts "metadata[:account_id]: #{sub.metadata[:account_id]}"
'

